<?php
namespace Xdecaro\Plugin\Task\Decarofinance\Extension;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Plugin\CMSPlugin; use Joomla\Component\Scheduler\Administrator\Event\ExecuteTaskEvent; use Joomla\Component\Scheduler\Administrator\Task\Status; use Joomla\Component\Scheduler\Administrator\Traits\TaskPluginTrait; use Joomla\Event\SubscriberInterface; use Throwable; use Xdecaro\Component\Decarofinance\Administrator\Extension\DecarofinanceComponent;
final class Decarofinance extends CMSPlugin implements SubscriberInterface { use TaskPluginTrait; protected const TASKS_MAP=['decarofinance.reminders'=>['langConstPrefix'=>'PLG_TASK_DECAROFINANCE_REMINDERS','form'=>'reminders','method'=>'processReminders']]; protected $autoloadLanguage=true; public static function getSubscribedEvents():array{return ['onTaskOptionsList'=>'advertiseRoutines','onExecuteTask'=>'standardRoutineHandler','onContentPrepareForm'=>'enhanceTaskItemForm'];} protected function processReminders(ExecuteTaskEvent $event):int { try{$component=Factory::getApplication()->bootComponent('com_decarofinance'); if(!$component instanceof DecarofinanceComponent)throw new \RuntimeException('Finance component unavailable.'); $stats=$component->getFinanceReminderService()->run(); $this->logTask(sprintf('Finance reminders: checked=%d notifications=%d tasks=%d',$stats['checked'],$stats['notifications'],$stats['tasks'])); return Status::OK;}catch(Throwable $e){$this->logTask('Finance reminders error: '.$e->getMessage(),'error'); return Status::KNOCKOUT;} } }
